import{a,_ as o}from"./chunks/m_btn_newtask.BnGNwNK5.js";import{_ as n,a as r,b as s,c,d as h,e as l,f as d,g,h as p,i as m,j as u}from"./chunks/m_ukol_z_fotky.CKuNbe3o.js";import{_ as t,a as k}from"./chunks/m_edit_fotky3.Tj88u-hW.js";import{_ as f}from"./chunks/m_edit_fotky2.IVXZ5228.js";import{_ as w,o as b,c as y,aa as _}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/cs/tickets/m_btn_foto.png",v="/buildary-help-preview/media/cs/tickets/m_btn_galerie.png",T="/buildary-help-preview/media/cs/tickets/m_btn_sponka.png",P="/buildary-help-preview/media/cs/tickets/m_ikona_hierar.png",z="/buildary-help-preview/media/cs/tickets/m_ikona_cil.png",E=JSON.parse('{"title":"New Ticket","description":"","frontmatter":{"title":"New Ticket","wiki":"en:tickets:m_task_new"},"headers":[],"relativePath":"en/tickets/m_task_new.md","filePath":"en/tickets/m_task_new.md","lastUpdated":1794388980000}'),x={name:"en/tickets/m_task_new.md"};function A(C,e,N,S,I,q){return b(),y("div",null,[...e[0]||(e[0]=[_('<h1 id="new-ticket" tabindex="-1">New Ticket <a class="header-anchor" href="#new-ticket" aria-label="Permalink to &quot;New Ticket&quot;">​</a></h1><p>A new ticket can be created from the <strong>Ticket List</strong> page in the standard way using the <img src="'+a+'" alt="New Ticket" width="30" data-no-zoom loading="lazy"> icon, or from a photo using the <img src="'+o+'" alt="New Photo for Creating a Ticket" width="30" data-no-zoom loading="lazy"> icon.</p><h2 id="_1-new-ticket-standard-ticket-creation" tabindex="-1">1/ New Ticket - Standard Ticket Creation <a class="header-anchor" href="#_1-new-ticket-standard-ticket-creation" aria-label="Permalink to &quot;1/ New Ticket - Standard Ticket Creation&quot;">​</a></h2><h2 id="basic-ticket-information" tabindex="-1">Basic Ticket Information <a class="header-anchor" href="#basic-ticket-information" aria-label="Permalink to &quot;Basic Ticket Information&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+n+'" alt="New Ticket" width="250" loading="lazy"></figure><figure class="shot" style="--w:270px;"><img src="'+r+'" alt="New Ticket - Completed Basic Information" width="250" loading="lazy"></figure><p>Creating a new ticket using the <img src="'+a+'" alt="New Ticket" width="30" data-no-zoom loading="lazy"> icon opens the form shown in the first image. After entering all the required information, the author <strong>saves the ticket using the checkmark icon</strong> <img src="'+t+'" alt="Checkmark" width="45" data-no-zoom loading="lazy"> in the bottom-right corner.</p><p>In the <strong>Subject</strong> field, the author enters the ticket name, preferably short and descriptive.</p><p>Below this field are the <strong>section tabs</strong>: <strong>Basic Information</strong> (current page) / <strong>Attachments</strong> / <strong>Drawings and Map</strong> / <strong>Participants</strong> (assignees and approvers) → we recommend completing the initial page first and only then switching to another section.</p><p>The <strong>Ticket Description</strong> field can be used to provide more details if everything is not clear from the Subject.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To enter the description, the user can use the <strong>microphone icon on the device keyboard</strong>. Pressing the icon <strong>activates speech-to-text</strong>. The function can be deactivated by pressing the icon again, or it will deactivate automatically after a longer period of silence. This device functionality can be used anywhere the keyboard appears after tapping an input field.</p></div><p><strong>Category</strong> displays a code list from which the author selects one option.</p><p><strong>Status</strong> is set to Not Started by default; the author can select another option from the code list.</p><p><strong>Priority</strong> is set to Medium by default and can be changed by the author.</p><p>If <strong>Labels</strong> have been created in Project Settings, the author can select one or more options.</p><p>At the bottom are the <strong>calendars</strong> → <strong>Planned Dates</strong> are set by default as follows: the start date is the current day on which the ticket is created / the end date is +7 days ⇒ the author can change these preset dates. <strong>Actual Dates</strong> cannot be specified by the author.</p><h2 id="ticket-attachments" tabindex="-1">Ticket Attachments <a class="header-anchor" href="#ticket-attachments" aria-label="Permalink to &quot;Ticket Attachments&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+s+'" alt="Ticket Attachments" width="250" loading="lazy"></figure><p><strong>The three active icons at the bottom of the screen</strong> can be used to add <strong>attachments</strong> to the ticket:</p><ul><li><strong>Camera icon <img src="'+i+'" alt="Switch to Camera" width="20" data-no-zoom loading="lazy"></strong> ⇒ switches the device to camera mode, allowing the author to immediately take photos for the ticket being created. The photos are automatically added to the Attachments section.</li><li><strong>Gallery icon <img src="'+v+'" alt="Select Photo from Gallery" width="20" data-no-zoom loading="lazy"></strong> ⇒ switches the device to the image gallery, where the author can select one or more saved photos / images for the ticket.</li><li><strong>Paperclip icon <img src="'+T+'" alt="Select Attachment" width="20" data-no-zoom loading="lazy"></strong> ⇒ opens a menu for selecting how to add an attachment. In addition to the two options above, the menu contains other options.</li></ul><img src="'+c+'" alt="Select Ticket Attachment" width="200" loading="lazy"><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Photos and videos taken immediately are not saved to the author&#39;s device. When the ticket is saved, they are uploaded directly to the server. This means they do not unnecessarily take up storage space on the device.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The icons for adding attachments are visible and active even when the user is not currently in the Attachments section. For example, if the user uses the camera icon and takes a photo, it is automatically saved to Attachments even if another ticket section is currently open.</p></div><h2 id="drawings-and-map" tabindex="-1">Drawings and Map <a class="header-anchor" href="#drawings-and-map" aria-label="Permalink to &quot;Drawings and Map&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+h+'" alt="Drawings and Map Section" width="250" loading="lazy"></figure><figure class="shot" style="--w:270px;"><img src="'+l+'" alt="Drawing with Markers" width="250" loading="lazy"></figure><p>The author can provide a more precise location for the ticket by <strong>placing markers on a drawing</strong> or by specifying a location on the map.</p><p>To use a drawing, it must first be uploaded in Project Settings. The author can then <strong>select the relevant drawing</strong> in several ways:</p><ol><li>the Project Part field is a text field; as characters are entered, the autocomplete will offer items containing those characters</li><li>the arrow icon at the end of the Project Part field expands the complete list of project parts, from which the author can select one</li><li>the <img src="'+P+'" alt="Project Structure Hierarchy Icon" width="25" data-no-zoom loading="lazy"> icon opens the list of project parts in a hierarchical structure, including the number of drawings assigned to each part</li><li>the Select Drawing icon opens a list of drawings displayed as thumbnails, allowing the author to select the drawing directly rather than selecting a project part</li></ol><p>Regardless of how the drawing was selected, it is displayed as a thumbnail in the drawing area.</p><p><strong>To add markers</strong>, simply tap the drawing itself or the Enter Markers option below it. The drawing opens in a new enlarged window, where it can be panned, zoomed in, zoomed out, etc. At the location where the marker should be placed, the author presses and holds their finger until the marker is created. Multiple markers can be added. If a marker needs to be moved or deleted, press and hold it until it becomes active, then move it to another location or to the trash icon that appears at the bottom of the screen. The drawing with markers must then be saved using <strong>OK</strong> in the top-right corner.</p><figure class="shot" style="--w:270px;"><img src="'+d+'" alt="Location on Map" width="250" loading="lazy"></figure><p>In the same section, below the drawing, there is a <strong>map</strong>. A marker can be placed on the map to <strong>localize the ticket location</strong>.</p><p>The marker can be created in two ways:</p><ol><li><strong>tap a point on the map</strong> → if the user does not hit the exact location and needs to move the marker, simply tap the correct point and the marker will move there</li><li><strong>tap the <img src="'+z+'" alt="Phone Location" width="25" data-no-zoom loading="lazy"> icon</strong> on the map → the marker is automatically placed at the coordinates of the device being used</li></ol><p>When a marker is placed on the drawing, <strong>the application automatically fills in the Project Location and GPS coordinates</strong>.</p><h2 id="ticket-participants" tabindex="-1">Ticket Participants <a class="header-anchor" href="#ticket-participants" aria-label="Permalink to &quot;Ticket Participants&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+g+'" alt="Ticket Participants" width="250" loading="lazy"></figure><p>Before saving the ticket, it is necessary to specify the <strong>assignees</strong> and, if applicable, the <strong>approvers</strong>.</p><p>The author selects them from a code list containing all Project Team Members for the project. Multiple people can be selected for each role.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the ticket creation meets an <strong>Assignees / Approvers Rule</strong>, the rule will be <strong>applied</strong> and the relevant roles will be assigned automatically according to the rule. This selection can still be changed in the ticket.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Save the ticket using the <img src="'+t+'" alt="Confirm New Ticket" width="45" data-no-zoom loading="lazy"> icon in the bottom-right corner.</strong></p></div><h2 id="_2-new-ticket-creating-a-ticket-from-a-photo" tabindex="-1">2/ New Ticket - Creating a Ticket from a Photo <a class="header-anchor" href="#_2-new-ticket-creating-a-ticket-from-a-photo" aria-label="Permalink to &quot;2/ New Ticket - Creating a Ticket from a Photo&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+p+'" alt="Ticket Photo" width="250" loading="lazy"></figure><p>Creating a new ticket using the <img src="'+o+'" alt="New Photo for Creating a Ticket" width="30" data-no-zoom loading="lazy"> icon switches the device to camera mode. After taking a photo and confirming it with the checkmark, the image is opened <strong>in editing mode</strong>, allowing the author to edit the photo before saving it. If no edits are made at this stage, they can be made later while editing the ticket.</p><p>The <img src="'+t+'" alt="Confirm" width="45" data-no-zoom loading="lazy"> icon in the bottom-right corner is used to <strong>save the photo and proceed to entering the ticket information</strong>.</p><p>If the author <strong>is not satisfied with the photo and wants to take another one</strong>, they can press the <img src="'+i+'" alt="Switch to Camera" width="25" data-no-zoom loading="lazy"> icon in the bottom-left corner ⇒ the device camera is activated again and the author can take a better photo for the ticket. <strong>The original photo will then be replaced by the new one.</strong></p><p>The <strong>back arrow</strong> in the top row <strong>cancels the entire action</strong> and returns to the Ticket List. <strong>IMPORTANT: The photo being left will not be saved!</strong></p><h2 id="photo-editing" tabindex="-1">Photo Editing <a class="header-anchor" href="#photo-editing" aria-label="Permalink to &quot;Photo Editing&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+m+'" alt="Editing Toolbar" width="250" loading="lazy"></figure><figure class="shot" style="--w:270px;"><img src="'+f+'" alt="Editing Functions" width="250" loading="lazy"></figure><p>If the user decides to edit the photo before saving it, they can use the functions in the <strong>editing toolbar below the photo</strong>.</p><p>The options for the selected function then open in an expanded menu in the associated toolbar below the image.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>After using the selected function, the user must <strong>confirm the change using the checkmark above the photo</strong>, and only then <strong>return to the editing options using the back arrow BELOW the image</strong>.</p></div><figure class="shot" style="--w:270px;"><img src="'+k+'" alt="Restore Previous Version" width="250" loading="lazy"></figure><p>During editing, the author can <strong>return to previous steps using the arrows above the image</strong>, or <strong>restore the original version before editing</strong> using the icon above the image on the right → after using it, <strong>all changes to the image are deleted and the edited version cannot be restored</strong>.</p><h2 id="completing-ticket-creation" tabindex="-1">Completing Ticket Creation <a class="header-anchor" href="#completing-ticket-creation" aria-label="Permalink to &quot;Completing Ticket Creation&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+u+'" alt="Completing Ticket Creation" width="250" loading="lazy"></figure><p>After the photo is saved, the application switches to the New Ticket form. The photo is automatically added to the Attachments section, and the author can enter the remaining ticket information.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The minimum required to save a ticket is the <strong>Ticket Subject</strong> and an assigned <strong>Assignee</strong>.</p></div><p>A description of all sections of the New Ticket form is provided above in the Standard Ticket Creation section.</p>',61)])])}const L=w(x,[["render",A]]);export{E as __pageData,L as default};
